WITH page_quarter_sales AS ( SELECT cp.cp_catalog_page_id, cp.cp_department, d.d_year, d.d_quarter_seq, SUM(ss.ss_ext_sales_price) AS total_sales, SUM(ss.ss_quantity) AS total_quantity, AVG(ss.ss_ext_discount_amt) AS avg_discount, COUNT(DISTINCT s.s_store_id) AS store_count FROM store_sales ss JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk JOIN store s ON ss.ss_store_sk = s.s_store_sk JOIN catalog_page cp ON d.d_date_sk BETWEEN cp.cp_start_date_sk AND cp.cp_end_date_sk GROUP BY cp.cp_catalog_page_id, cp.cp_department, d.d_year, d.d_quarter_seq ) SELECT cp_catalog_page_id, cp_department, d_year, d_quarter_seq, total_sales, total_quantity, avg_discount, store_count, SUM(total_sales) OVER (PARTITION BY cp_department ORDER BY d_year, d_quarter_seq ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_sales, DENSE_RANK() OVER (PARTITION BY cp_department ORDER BY total_sales DESC) AS dept_page_rank, CASE WHEN total_sales > 100000 THEN 'High' ELSE 'Normal' END AS sales_flag FROM page_quarter_sales ORDER BY cp_department, dept_page_rank LIMIT 200
